<?php
require __DIR__.'/../includes/bootstrap.php';
require_role('admin');
$slots=['header-banner'=>['Header Banner',728,90],'article-inline-30'=>['In-Article Block 1 (after 30% of content)',728,90],'article-inline-55'=>['In-Article Block 2 (after 55% of content)',728,90],'article-inline-75'=>['In-Article Block 3 (after 75% of content)',728,90],'article-inline'=>['Legacy In-Article Fallback',728,90],'sidebar-rectangle'=>['Sidebar Rectangle',300,250],'sidebar-skyscraper'=>['Sidebar Skyscraper',160,600],'sidebar-large'=>['Sidebar Large',300,600],'mobile-banner'=>['Mobile Banner',320,100],'footer-banner'=>['Footer Banner',728,90]];
$id=(int)($_GET['id']??0);$ad=['name'=>'','slot'=>'','html_code'=>'','width'=>0,'height'=>0,'status'=>'inactive'];$error='';
if($pdo&&$id){$s=$pdo->prepare('SELECT * FROM advertisements WHERE id=?');$s->execute([$id]);$ad=$s->fetch()?:$ad;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(['name','slot','html_code','status'] as $field)$ad[$field]=trim($_POST[$field]??'');if(!isset($slots[$ad['slot']]))$error='Select a valid advertisement slot.';elseif($ad['name']===''||$ad['html_code']==='')$error='Name and advertisement code are required.';elseif(!in_array($ad['status'],['active','inactive'],true))$error='Invalid status.';else{[, $ad['width'],$ad['height']]=$slots[$ad['slot']];if($id){$s=$pdo->prepare('UPDATE advertisements SET name=?,slot=?,html_code=?,width=?,height=?,status=? WHERE id=?');$s->execute([$ad['name'],$ad['slot'],$ad['html_code'],$ad['width'],$ad['height'],$ad['status'],$id]);log_admin_activity('advertisement_updated','Advertisement ID: '.$id);}else{$s=$pdo->prepare('INSERT INTO advertisements(name,slot,html_code,width,height,status) VALUES(?,?,?,?,?,?)');$s->execute([$ad['name'],$ad['slot'],$ad['html_code'],$ad['width'],$ad['height'],$ad['status']]);log_admin_activity('advertisement_created','Advertisement ID: '.$pdo->lastInsertId());}header('Location: advertisements.php');exit;}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Advertisement</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1><?=e($id?'Edit Advertisement':'New Advertisement')?></h1><?php if($error):?><p role="alert"><?=e($error)?></p><?php endif;?><form method="post" class="card"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><p><label>Name<input name="name" value="<?=e($ad['name'])?>" required></label></p><p><label>Slot<select name="slot" required><option value="">Select slot</option><?php foreach($slots as $value=>$details):?><option value="<?=e($value)?>" <?=$ad['slot']===$value?'selected':''?>><?=e($details[0].' ('.$details[1].'x'.$details[2].')')?></option><?php endforeach;?></select></label></p><p><label>Advertisement code<textarea name="html_code" rows="8" required><?=e($ad['html_code'])?></textarea></label></p><p class="muted">Paste the original script tag without backslashes or Markdown formatting.</p><p class="muted">The three in-article blocks appear after 30%, 55%, and 75% of the article content. The legacy in-article slot is used only as a fallback when a block has no active advertisement.</p><p><label>Status<select name="status"><option value="inactive" <?=$ad['status']==='inactive'?'selected':''?>>Inactive</option><option value="active" <?=$ad['status']==='active'?'selected':''?>>Active</option></select></label></p><button>Save advertisement</button> <a href="advertisements.php">Cancel</a></form></main></body></html>
